-- 014: Atomic quote creation and payment-schedule writes

BEGIN;

-- Quote numbers are generated by MAX(existing)+1. Serialize that calculation
-- per calendar year so concurrent inserts cannot choose the same number.
CREATE OR REPLACE FUNCTION generate_quote_number()
RETURNS TRIGGER AS $$
DECLARE
  year_prefix VARCHAR(4);
  next_number INTEGER;
BEGIN
  IF NEW.quote_number IS NULL THEN
    year_prefix := TO_CHAR(NOW(), 'YYYY');
    PERFORM pg_advisory_xact_lock(hashtext('quote-number:' || year_prefix));

    SELECT COALESCE(MAX(
      CAST(SUBSTRING(quote_number FROM '\d+$') AS INTEGER)
    ), 0) + 1
    INTO next_number
    FROM quotes
    WHERE quote_number LIKE 'Q-' || year_prefix || '-%';

    NEW.quote_number :=
      'Q-' || year_prefix || '-' || LPAD(next_number::TEXT, 3, '0');
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION create_quote_atomic(
  p_user_id UUID,
  p_client_id UUID,
  p_client_info JSONB,
  p_project_name TEXT,
  p_discount_amount NUMERIC,
  p_notes TEXT,
  p_internal_notes TEXT,
  p_line_items JSONB
)
RETURNS TABLE (
  quote_id UUID,
  quote_number TEXT,
  quota_exceeded BOOLEAN,
  resolved_tier TEXT,
  quote_limit INTEGER
)
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_tier TEXT;
  v_limit INTEGER;
  v_used INTEGER;
  v_contact_id UUID;
  v_quote_id UUID;
  v_quote_number TEXT;
  v_email TEXT;
BEGIN
  IF p_line_items IS NULL
     OR jsonb_typeof(p_line_items) <> 'array'
     OR jsonb_array_length(p_line_items) = 0 THEN
    RAISE EXCEPTION 'INVALID_LINE_ITEMS' USING ERRCODE = 'P0001';
  END IF;

  -- This row lock is the quota mutex for a user. Contact resolution is kept
  -- under the same lock so exact-email fallback cannot create duplicates.
  SELECT u.subscription_tier
  INTO v_tier
  FROM users u
  WHERE u.id = p_user_id AND u.deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'USER_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF v_tier IS NULL OR v_tier NOT IN ('free', 'pro', 'ultimate') THEN
    v_tier := 'free';
  END IF;

  v_limit := CASE v_tier
    WHEN 'free' THEN 3
    WHEN 'pro' THEN 15
    ELSE NULL
  END;

  IF v_limit IS NOT NULL THEN
    SELECT COUNT(*)
    INTO v_used
    FROM quotes q
    WHERE q.user_id = p_user_id
      AND q.deleted_at IS NULL
      AND q.created_at >=
        (date_trunc('month', NOW() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC');

    IF v_used >= v_limit THEN
      RETURN QUERY
      SELECT NULL::UUID, NULL::TEXT, TRUE, v_tier, v_limit;
      RETURN;
    END IF;
  END IF;

  IF p_client_id IS NOT NULL THEN
    SELECT c.id
    INTO v_contact_id
    FROM contacts c
    WHERE c.id = p_client_id
      AND c.user_id = p_user_id
      AND c.deleted_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'CONTACT_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;
  ELSE
    v_email := NULLIF(LOWER(BTRIM(p_client_info ->> 'email')), '');

    IF v_email IS NOT NULL THEN
      SELECT c.id
      INTO v_contact_id
      FROM contacts c
      WHERE c.user_id = p_user_id
        AND c.deleted_at IS NULL
        AND LOWER(c.email) = v_email
      ORDER BY c.created_at ASC
      LIMIT 1;
    END IF;

    IF v_contact_id IS NULL THEN
      INSERT INTO contacts (
        user_id, name, email, phone, company, address, city, state, zip_code
      ) VALUES (
        p_user_id,
        BTRIM(p_client_info ->> 'name'),
        NULLIF(BTRIM(p_client_info ->> 'email'), ''),
        NULLIF(BTRIM(p_client_info ->> 'phone'), ''),
        NULLIF(BTRIM(p_client_info ->> 'company'), ''),
        NULLIF(BTRIM(p_client_info ->> 'address'), ''),
        NULLIF(BTRIM(p_client_info ->> 'city'), ''),
        NULLIF(BTRIM(p_client_info ->> 'state'), ''),
        NULLIF(BTRIM(p_client_info ->> 'zipCode'), '')
      )
      RETURNING id INTO v_contact_id;
    END IF;
  END IF;

  INSERT INTO quotes (
    user_id, contact_id, project_name, discount_amount, notes, internal_notes
  ) VALUES (
    p_user_id,
    v_contact_id,
    p_project_name,
    p_discount_amount,
    p_notes,
    p_internal_notes
  )
  RETURNING id, quotes.quote_number INTO v_quote_id, v_quote_number;

  INSERT INTO quote_line_items (
    quote_id,
    description,
    quantity,
    unit_price,
    total,
    unit_of_measure,
    work_item_id,
    sort_order
  )
  SELECT
    v_quote_id,
    item ->> 'description',
    (item ->> 'quantity')::NUMERIC,
    (item ->> 'unitPrice')::NUMERIC,
    (item ->> 'quantity')::NUMERIC * (item ->> 'unitPrice')::NUMERIC,
    COALESCE(NULLIF(item ->> 'unit', ''), 'ea'),
    NULLIF(item ->> 'workItemId', '')::UUID,
    (ordinality - 1)::INTEGER
  FROM jsonb_array_elements(p_line_items) WITH ORDINALITY AS lines(item, ordinality);

  INSERT INTO payment_milestones (
    quote_id, user_id, name, percentage, sort_order
  ) VALUES
    (v_quote_id, p_user_id, 'Deposit', 10, 0),
    (v_quote_id, p_user_id, 'Before construction starts', 30, 1),
    (v_quote_id, p_user_id, 'During the work', 30, 2),
    (v_quote_id, p_user_id, 'On completion', 30, 3);

  RETURN QUERY
  SELECT v_quote_id, v_quote_number, FALSE, v_tier, v_limit;
END;
$$;

CREATE OR REPLACE FUNCTION ensure_default_payment_schedule(
  p_quote_id UUID,
  p_user_id UUID
)
RETURNS SETOF payment_milestones
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  PERFORM 1
  FROM quotes q
  WHERE q.id = p_quote_id
    AND q.user_id = p_user_id
    AND q.deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'QUOTE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM payment_milestones pm
    WHERE pm.quote_id = p_quote_id AND pm.user_id = p_user_id
  ) THEN
    INSERT INTO payment_milestones (
      quote_id, user_id, name, percentage, sort_order
    ) VALUES
      (p_quote_id, p_user_id, 'Deposit', 10, 0),
      (p_quote_id, p_user_id, 'Before construction starts', 30, 1),
      (p_quote_id, p_user_id, 'During the work', 30, 2),
      (p_quote_id, p_user_id, 'On completion', 30, 3);
  END IF;

  RETURN QUERY
  SELECT pm.*
  FROM payment_milestones pm
  WHERE pm.quote_id = p_quote_id AND pm.user_id = p_user_id
  ORDER BY pm.sort_order ASC;
END;
$$;

CREATE OR REPLACE FUNCTION replace_payment_schedule_atomic(
  p_quote_id UUID,
  p_user_id UUID,
  p_milestones JSONB
)
RETURNS SETOF payment_milestones
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_item JSONB;
  v_sum NUMERIC;
BEGIN
  PERFORM 1
  FROM quotes q
  WHERE q.id = p_quote_id
    AND q.user_id = p_user_id
    AND q.deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'QUOTE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF p_milestones IS NULL
     OR jsonb_typeof(p_milestones) <> 'array'
     OR jsonb_array_length(p_milestones) = 0
     OR jsonb_array_length(p_milestones) > 20 THEN
    RAISE EXCEPTION 'INVALID_SCHEDULE' USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_milestones) AS supplied(item)
    WHERE NULLIF(item ->> 'id', '') IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM payment_milestones pm
        WHERE pm.id = (item ->> 'id')::UUID
          AND pm.quote_id = p_quote_id
          AND pm.user_id = p_user_id
      )
  ) THEN
    RAISE EXCEPTION 'MILESTONE_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF (
    SELECT COUNT(NULLIF(item ->> 'id', ''))
    FROM jsonb_array_elements(p_milestones) AS supplied(item)
  ) <> (
    SELECT COUNT(DISTINCT NULLIF(item ->> 'id', ''))
    FROM jsonb_array_elements(p_milestones) AS supplied(item)
  ) THEN
    RAISE EXCEPTION 'DUPLICATE_MILESTONE_ID' USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_milestones) AS supplied(item)
    WHERE BTRIM(COALESCE(item ->> 'name', '')) = ''
      OR (item ->> 'percentage')::NUMERIC <= 0
      OR (item ->> 'percentage')::NUMERIC > 100
  ) THEN
    RAISE EXCEPTION 'INVALID_MILESTONE' USING ERRCODE = 'P0001';
  END IF;

  SELECT SUM((item ->> 'percentage')::NUMERIC)
  INTO v_sum
  FROM jsonb_array_elements(p_milestones) AS supplied(item);

  IF ABS(v_sum - 100) > 0.001 THEN
    RAISE EXCEPTION 'INVALID_SCHEDULE_TOTAL' USING ERRCODE = 'P0001';
  END IF;

  -- A paid milestone cannot be omitted. Checking explicitly makes the
  -- integrity rule clear; the FK would also roll the transaction back.
  IF EXISTS (
    SELECT 1
    FROM payment_milestones pm
    JOIN quote_payments qp ON qp.milestone_id = pm.id
    WHERE pm.quote_id = p_quote_id
      AND pm.user_id = p_user_id
      AND NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_milestones) AS supplied(item)
        WHERE NULLIF(item ->> 'id', '')::UUID = pm.id
      )
  ) THEN
    RAISE EXCEPTION 'PAID_MILESTONE_REMOVAL' USING ERRCODE = 'P0001';
  END IF;

  DELETE FROM payment_milestones pm
  WHERE pm.quote_id = p_quote_id
    AND pm.user_id = p_user_id
    AND NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_milestones) AS supplied(item)
      WHERE NULLIF(item ->> 'id', '')::UUID = pm.id
    );

  FOR v_item IN SELECT item FROM jsonb_array_elements(p_milestones) AS supplied(item)
  LOOP
    IF NULLIF(v_item ->> 'id', '') IS NULL THEN
      INSERT INTO payment_milestones (
        quote_id, user_id, name, percentage, sort_order
      ) VALUES (
        p_quote_id,
        p_user_id,
        BTRIM(v_item ->> 'name'),
        (v_item ->> 'percentage')::NUMERIC,
        (v_item ->> 'sortOrder')::INTEGER
      );
    ELSE
      UPDATE payment_milestones
      SET
        name = BTRIM(v_item ->> 'name'),
        percentage = (v_item ->> 'percentage')::NUMERIC,
        sort_order = (v_item ->> 'sortOrder')::INTEGER
      WHERE id = (v_item ->> 'id')::UUID
        AND quote_id = p_quote_id
        AND user_id = p_user_id;
    END IF;
  END LOOP;

  RETURN QUERY
  SELECT pm.*
  FROM payment_milestones pm
  WHERE pm.quote_id = p_quote_id AND pm.user_id = p_user_id
  ORDER BY pm.sort_order ASC;
END;
$$;

REVOKE ALL ON FUNCTION create_quote_atomic(UUID, UUID, JSONB, TEXT, NUMERIC, TEXT, TEXT, JSONB)
  FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION ensure_default_payment_schedule(UUID, UUID)
  FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION replace_payment_schedule_atomic(UUID, UUID, JSONB)
  FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION create_quote_atomic(UUID, UUID, JSONB, TEXT, NUMERIC, TEXT, TEXT, JSONB)
  TO service_role;
GRANT EXECUTE ON FUNCTION ensure_default_payment_schedule(UUID, UUID)
  TO service_role;
GRANT EXECUTE ON FUNCTION replace_payment_schedule_atomic(UUID, UUID, JSONB)
  TO service_role;

COMMIT;
